package authz

import (
	"encoding/json"
	"os"
	"sort"
	"testing"
)

// vectors.json: requests with the decision the Next.js policy makes,
// generated by tests/unit/authz-go-policy.test.ts.
type vectorFile struct {
	TenantID string `json:"tenantId"`
	Subjects []struct {
		ID          string          `json:"id"`
		Role        string          `json:"role"`
		Plan        string          `json:"plan"`
		Permissions []string        `json:"permissions"`
		Claim       json.RawMessage `json:"claim"`
	} `json:"subjects"`
	Requests []struct {
		Method            string  `json:"method"`
		Pathname          string  `json:"pathname"`
		RequestedTenantID *string `json:"requestedTenantId"`
	} `json:"requests"`
	// [request index, subject index, allow, reason, area|null, required|null]
	Cases [][]any `json:"cases"`
}

func loadVectors(t *testing.T) vectorFile {
	t.Helper()
	data, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v vectorFile
	if err := json.Unmarshal(data, &v); err != nil {
		t.Fatal(err)
	}
	if len(v.Cases) < 500 {
		t.Fatalf("only %d vectors", len(v.Cases))
	}
	return v
}

func str(v any) string {
	if s, ok := v.(string); ok {
		return s
	}
	return ""
}

// Go decides every request exactly as Next.js does.
func TestDecideMatchesNextJS(t *testing.T) {
	v := loadVectors(t)
	p := Default()
	for _, c := range v.Cases {
		req := v.Requests[int(c[0].(float64))]
		sub := v.Subjects[int(c[1].(float64))]
		// The permissions come from the signed claim, as they do from a token.
		perms := p.DecodeClaim(sub.Claim)
		r := Request{Pathname: req.Pathname, Method: req.Method}
		if req.RequestedTenantID != nil {
			r.RequestedTenantID = *req.RequestedTenantID
		}
		got := p.Decide(r, Subject{Role: sub.Role, TenantID: v.TenantID, Plan: sub.Plan, Permissions: perms})
		wantAllow, wantReason, wantArea, wantRequired := c[2].(bool), str(c[3]), str(c[4]), str(c[5])
		if got.Allow != wantAllow || got.Reason != wantReason || got.Area != wantArea || got.Required != wantRequired {
			t.Errorf("%s %s as %s: go {%v %s %s %s}, next {%v %s %s %s}",
				req.Method, req.Pathname, sub.ID,
				got.Allow, got.Reason, got.Area, got.Required,
				wantAllow, wantReason, wantArea, wantRequired)
		}
	}
}

// The claim decodes to exactly the permissions it was built from.
func TestDecodeClaimMatchesNextJS(t *testing.T) {
	v := loadVectors(t)
	p := Default()
	for _, s := range v.Subjects {
		got := p.DecodeClaim(s.Claim)
		if s.Permissions == nil {
			if got != nil {
				t.Errorf("%s: want no claim, got %v", s.ID, got)
			}
			continue
		}
		want := append([]string(nil), s.Permissions...)
		sort.Strings(want)
		have := append([]string(nil), got...)
		sort.Strings(have)
		if len(want) != len(have) {
			t.Fatalf("%s: %d permissions, want %d", s.ID, len(have), len(want))
		}
		for i := range want {
			if want[i] != have[i] {
				t.Errorf("%s: %q != %q", s.ID, have[i], want[i])
			}
		}
	}
}

func TestDecodeClaimRejectsOtherCatalogues(t *testing.T) {
	p := Default()
	if p.DecodeClaim(json.RawMessage(`{"v":"00000000","b":"AA"}`)) != nil {
		t.Error("claim from another catalogue version accepted")
	}
	if p.DecodeClaim(json.RawMessage(`{"v":"`+p.CatalogueVersion+`","b":"!!"}`)) != nil {
		t.Error("malformed bitset accepted")
	}
	if p.DecodeClaim(nil) != nil || p.DecodeClaim(json.RawMessage("null")) != nil {
		t.Error("absent claim decoded")
	}
}
